  ('function_owner', (SELECT count(*) FROM unnest(ARRAY['creator_record_v2_examination_uat_grant_guard()', 'creator_record_v2_examination_environment_exclusivity()', 'creator_record_v2_documents_provenance_guard()', 'creator_record_v2_documents_seed_binding()', 'creator_record_v2_prepared_documents_origin_guard()', 'creator_record_v2_examination_uat_status(text)', 'creator_record_v2_evidence_access_log_insert_guard()', 'creator_record_v2_record_examination(bigint,text)']) f(sig) JOIN pg_proc p ON p.oid = to_regprocedure('public.' || f.sig)
      WHERE p.proowner = (SELECT relowner FROM pg_class WHERE oid = 'public.creator_record_v2_documents'::regclass)) = 8),
  ('function_execute', (SELECT coalesce(array_agg(f.sig || ':' || r.role ORDER BY f.sig || ':' || r.role COLLATE "C"), ARRAY[]::text[])
       FROM unnest(ARRAY['creator_record_v2_append_only_guard()', 'creator_record_v2_documents_guard()', 'creator_record_v2_prepared_documents_link()', 'creator_record_v2_jsonb_exact_keys(jsonb,text[])', 'creator_record_v2_examination_environment_guard()', 'creator_record_v2_examination_append_only_guard()', 'creator_record_v2_examination_uat_grant_guard()', 'creator_record_v2_examination_environment_exclusivity()', 'creator_record_v2_documents_provenance_guard()', 'creator_record_v2_documents_seed_binding()', 'creator_record_v2_prepared_documents_origin_guard()', 'creator_record_v2_examination_uat_status(text)', 'creator_record_v2_evidence_access_log_insert_guard()', 'creator_record_v2_record_examination(bigint,text)']) f(sig), unnest(ARRAY['anon', 'authenticated', 'public', 'service_role']) r(role)
      WHERE coalesce(has_function_privilege(r.role, to_regprocedure('public.' || f.sig), 'EXECUTE'), false))
    = ARRAY['creator_record_v2_examination_uat_status(text):service_role', 'creator_record_v2_record_examination(bigint,text):service_role']),
  ('doc1_function_bodies', (SELECT count(*) = 3 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND (p.proname::text, md5(p.prosrc)) IN (
       ('creator_record_v2_append_only_guard', '853241fdf43eebd7a783cc6b633bc1dd'), ('creator_record_v2_append_only_guard', '509db484094209260f0378431fe917f8'),
       ('creator_record_v2_documents_guard', '16acef5be434a536c6527f05a5c64cb7'), ('creator_record_v2_documents_guard', 'c7137201b1f6bcf2e7f7f871a0b9ccb3'),
       ('creator_record_v2_prepared_documents_link', '98f1183d8e42468347e10f8de1c1a15b'), ('creator_record_v2_prepared_documents_link', 'cf2fee7f2acf902eaef69dd0cc2dee9c'))))
