         AND r.user_id = '45f0d04f-4082-42ba-b65e-d8e28a3fc8bf' AND r.uat_grant_id = '27d8c027-44d0-4c4a-91fb-fa8ba5518848' AND r.execution_boundary = 'operator_synthetic_uat'
