         AND l.actor_user_id = '45f0d04f-4082-42ba-b65e-d8e28a3fc8bf' AND l.uat_grant_id = '27d8c027-44d0-4c4a-91fb-fa8ba5518848' AND r.id = '5a2f9a72-1ae5-4db0-9d27-7dbee34ff697') THEN
